//! Parsing of a view's generated regions. A region opens with
//! `<!-- generated by: <command> | inputs: <glob>[, <glob>...] | sha256: <hex> -->`
//! and closes with `<!-- end generated -->`. The older opening line
//! `<!-- generated by: <command> -->` carries no inputs and no hash and parses
//! as an unstamped region. The binary never runs the command.

use std::fmt;
use std::ops::Range;

const OPENING: &str = "<!-- generated by:";
const CLOSING: &str = "<!-- end generated -->";
const INPUTS_KEY: &str = " | inputs: ";
const HASH_KEY: &str = " | sha256: ";
const UNCLOSED: &str = "opening marker with no closing end-generated marker";

/// One generated region of a view body.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Region {
    /// The command text of the opening marker, never run by the binary.
    pub command: String,
    /// The input globs the region was stamped with; empty when unstamped.
    pub inputs: Vec<String>,
    /// The stamped lowercase-hex SHA-256 of the inputs; `None` when unstamped.
    pub hash: Option<String>,
    /// The 1-based line numbers of the content between the markers, as a
    /// half-open range: it starts on the line after the opening marker and
    /// ends at the closing marker's line, so an empty region has `start == end`.
    pub span: Range<usize>,
}

/// A malformed marker, naming the 1-based line it was found on.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RegionError {
    /// The 1-based line of the offending marker.
    pub line: usize,
    /// What is wrong with it.
    pub message: String,
}

impl fmt::Display for RegionError {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(out, "line {}: {}", self.line, self.message)
    }
}

impl std::error::Error for RegionError {}

/// The opening marker line of a stamped region: parsing it gives back the
/// command, the globs and the hash it was built from.
pub fn render_opening(command: &str, inputs: &[String], hash: &str) -> String {
    let globs = inputs.join(", ");
    format!("{OPENING} {command}{INPUTS_KEY}{globs}{HASH_KEY}{hash} -->")
}

/// The closing marker line of a region.
pub fn render_closing() -> &'static str {
    CLOSING
}

/// Parses every generated region of `body`, in order. Markers inside a fenced
/// code block are not markers; a fenced block inside a region is its content.
/// Fails on a malformed stamped marker, an opening with no closing (naming the
/// opening line) or a closing with no opening.
pub fn parse_regions(body: &str) -> Result<Vec<Region>, RegionError> {
    let mut regions = Vec::new();
    let mut open: Option<(usize, Region)> = None;
    let mut fence: Option<(char, usize)> = None;
    for (index, text) in body.lines().enumerate() {
        let line = index + 1;
        match marker_at(text, line, &mut fence)? {
            Marker::None => {}
            Marker::Closing => {
                let Some((_, mut region)) = open.take() else {
                    return Err(error(line, "closing marker with no opening"));
                };
                region.span.end = line;
                regions.push(region);
            }
            Marker::Opening(region) => {
                if let Some((first, _)) = open {
                    return Err(error(first, UNCLOSED));
                }
                open = Some((line, region));
            }
        }
    }
    match open {
        Some((first, _)) => Err(error(first, UNCLOSED)),
        None => Ok(regions),
    }
}

/// What one line of a body is, outside any fenced block.
enum Marker {
    None,
    Opening(Region),
    Closing,
}

/// Classifies the line `text`, updating the fence state it sits in.
fn marker_at(
    text: &str,
    line: usize,
    fence: &mut Option<(char, usize)>,
) -> Result<Marker, RegionError> {
    if toggle_fence(text, fence) || fence.is_some() {
        return Ok(Marker::None);
    }
    let trimmed = text.trim();
    if trimmed == CLOSING {
        return Ok(Marker::Closing);
    }
    Ok(parse_opening(trimmed, line)?.map_or(Marker::None, Marker::Opening))
}

fn error(line: usize, message: &str) -> RegionError {
    RegionError {
        line,
        message: message.to_string(),
    }
}

/// Updates `fence` for a fence line and reports whether `text` was one. A
/// backtick fence's info string holds no backtick, as in CommonMark, so such a
/// line is no fence.
fn toggle_fence(text: &str, fence: &mut Option<(char, usize)>) -> bool {
    let indent = text.len() - text.trim_start_matches(' ').len();
    let rest = &text[indent..];
    let Some(mark) = rest.chars().next().filter(|c| matches!(c, '`' | '~')) else {
        return false;
    };
    let run = rest.chars().take_while(|c| *c == mark).count();
    if indent > 3 || run < 3 {
        return false;
    }
    match *fence {
        None if mark == '`' && rest[run..].contains('`') => return false,
        None => *fence = Some((mark, run)),
        Some((open, width)) if open == mark && run >= width && rest[run..].trim().is_empty() => {
            *fence = None;
        }
        Some(_) => return false,
    }
    true
}

/// The region an opening marker line starts, or `None` when `trimmed` is not
/// an opening marker. The command is whatever precedes the last ` | inputs: `,
/// so a legacy command holding a pipe stays whole.
fn parse_opening(trimmed: &str, line: usize) -> Result<Option<Region>, RegionError> {
    let Some(rest) = trimmed.strip_prefix(OPENING) else {
        return Ok(None);
    };
    let Some(inner) = rest.strip_suffix("-->") else {
        return Ok(None);
    };
    let (command, inputs, hash) = split_stamp(inner.trim_end(), line)?;
    let command = command.trim();
    if command.is_empty() {
        return Err(error(line, "opening marker names no command"));
    }
    Ok(Some(Region {
        command: command.to_string(),
        inputs,
        hash,
        span: line + 1..line + 1,
    }))
}

/// Splits an opening marker's text into its command, input globs and hash,
/// refusing a stamp that holds only one of the two.
fn split_stamp(
    inner: &str,
    line: usize,
) -> Result<(&str, Vec<String>, Option<String>), RegionError> {
    let (command, inputs, hash) = split_keys(inner, line)?;
    match (inputs, hash) {
        (None, None) => Ok((command, Vec::new(), None)),
        (Some(_), None) => Err(error(line, "inputs without a sha256")),
        (None, Some(_)) => Err(error(line, "sha256 without inputs")),
        (Some(inputs), Some(hash)) => Ok((
            command,
            split_inputs(inputs, line)?,
            Some(valid_hash(hash, line)?),
        )),
    }
}

/// Splits `inner` at its ` | inputs: ` and ` | sha256: ` keys, refusing a key
/// given twice.
fn split_keys(inner: &str, line: usize) -> Result<(&str, Option<&str>, Option<&str>), RegionError> {
    let (head, hash) = match inner.rsplit_once(HASH_KEY) {
        Some((head, hash)) => (head, Some(hash.trim())),
        None => (inner, None),
    };
    let (command, inputs) = match head.rsplit_once(INPUTS_KEY) {
        Some((command, inputs)) => (command, Some(inputs)),
        None => (head, None),
    };
    if head.contains(HASH_KEY) || command.contains(INPUTS_KEY) {
        return Err(error(line, "a marker key is given twice"));
    }
    Ok((command, inputs, hash))
}

fn split_inputs(text: &str, line: usize) -> Result<Vec<String>, RegionError> {
    let globs: Vec<String> = text
        .split(',')
        .map(|glob| glob.trim().to_string())
        .collect();
    if globs.iter().any(String::is_empty) {
        return Err(error(line, "inputs holds an empty glob"));
    }
    Ok(globs)
}

fn valid_hash(hash: &str, line: usize) -> Result<String, RegionError> {
    let lowercase_hex = |c: char| c.is_ascii_digit() || ('a'..='f').contains(&c);
    if hash.len() == 64 && hash.chars().all(lowercase_hex) {
        Ok(hash.to_string())
    } else {
        Err(error(line, "sha256 must be 64 lowercase hex characters"))
    }
}

